/* Built-in food photos (embedded, so they work no matter where the Images folder is) */
window.PICKAGO_IMAGES = {
  'chicken-adobo': 'data:image/jpeg;base64,',
  'veggie-lumpia': 'data:image/jpeg;base64,',
  'spaghetti-hotdog': 'data:image/jpeg;base64,',
  'calamansi-tea': 'data:image/jpeg;base64,',
  'ube-pandesal': 'data:image/jpeg;base64,',
  'banana-cue': 'data:image/jpeg;base64,'
};
/* Turns a saved image path into something the browser can show. */
function imgSrc(path) {
  const p = String(path || '');
  if (!p || /^(data:|https?:|blob:)/.test(p)) return p;
  let base = p.split('/').pop().replace(/\.[a-z0-9]+$/i, '');
  const key = (typeof IMAGE_RENAMES !== 'undefined' && IMAGE_RENAMES[p.split('/').pop()]) || base;
  const k = String(key).replace(/\.[a-z0-9]+$/i, '');
  return window.PICKAGO_IMAGES[k] || p;
}

/* Foods saved without a photo get their built-in photo (matched by name), once. */
const DEFAULT_PHOTOS = {
  'Chicken Adobo Rice Bowl': '../Images/chicken-adobo.png',
  'Veggie Lumpia': '../Images/veggie-lumpia.png',
  'Spaghetti with Hotdog': '../Images/spaghetti-hotdog.png',
  'Iced Calamansi Tea': '../Images/calamansi-tea.png',
  'Ube Cheese Pandesal': '../Images/ube-pandesal.png',
  'Banana Cue': '../Images/banana-cue.png'
};
function fillDefaultPhotos(list) {
  let changed = false;
  list.forEach((f) => {
    const p = f && !f.image && DEFAULT_PHOTOS[String(f.name || '').trim()];
    if (p) { f.image = p; changed = true; }
  });
  return changed;
}
